 using (auth_user_id=(select auth.uid()) or private.has_staff_section('team'));

create policy portal_omg_commission_scope on public.omg_store_commission_months as restrictive for select to anon,authenticated
 using (private.has_staff_section('commission_admin') or (private.has_staff_section('commissions') and rep_id=(select id from public.team_members where auth_id=auth.uid() limit 1)));

-- Relocate privileged implementations to a non-exposed schema. Public wrappers authorize first.
do $wrap$
declare f record; required text[]; args text; result text; callargs text; guard text; body text; signature text;
 rpc constant jsonb:='{"advance_job_stage":["production","jobs"],"box_merge":["warehouse"],"merge_product_inventory":["inventory"],"pull_house_inventory":["warehouse"],"pull_store_inventory":["warehouse"],"pull_webstore_transfers":["warehouse"],"get_sales_report":["reports"],"get_sales_report_detail":["reports"],"create_purchase_order":["purchase_orders"],"create_store_inventory_po":["purchase_orders"],"receive_store_inventory_po":["warehouse"],"close_store_inventory_po":["purchase_orders"],"set_store_opening_inventory_cost":["inventory"],"clone_webstore_atomic":["webstores"],"finalize_webstore_batch":["webstores"],"apply_webstore_order_item_edits":["webstores"],"claim_batch_po_number":["batch_pos","orders","purchase_orders"],"reserve_po_number":["orders","purchase_orders"],"reserve_po_numbers":["orders","purchase_orders"],"reserve_po_block":["orders","purchase_orders"],"next_counter":["orders","estimates","invoices","customers","webstores","warehouse"],"recover_deleted":["backup"],"row_history":["backup"],"reserve_methodic_payment":["methodic"],"app_state_cas":["@app_state"]}'::jsonb;
begin
 for f in select p.*,n.nspname,l.lanname from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and p.prokind='f' and p.prosecdef and p.prorettype not in ('trigger'::regtype,'event_trigger'::regtype) loop
  if f.proname in ('is_team_member','is_admin_member','is_quickbooks_member','current_user_role','current_profile_id','is_admin','is_admin_or_gm','is_gl_admin','get_my_profile','link_team_auth','link_my_team_auth','get_staff_directory','staff_section_for_auth') then continue; end if;
  if not (rpc ? f.proname) then
   execute format('revoke all on function %I.%I(%s) from public,anon,authenticated',f.nspname,f.proname,pg_get_function_identity_arguments(f.oid));
   execute format('grant execute on function %I.%I(%s) to service_role',f.nspname,f.proname,pg_get_function_identity_arguments(f.oid));
   continue;
  end if;
  args:=pg_get_function_arguments(f.oid); result:=pg_get_function_result(f.oid); signature:=pg_get_function_identity_arguments(f.oid);
  select string_agg(format('%I',f.proargnames[i]),',' order by i) into callargs from generate_series(1,f.pronargs) i;
  if callargs is null and f.pronargs>0 then raise exception 'Unnamed RPC arguments: %',f.proname; end if;
  select array_agg(value) into required from jsonb_array_elements_text(rpc->f.proname);
  guard:=case when f.proname='app_state_cas' then 'perform private.require_staff_section(private.app_state_sections(p_key));' else format('perform private.require_staff_section(%L::text[]);',required) end;
  execute format('alter function public.%I(%s) set schema private',f.proname,signature);
  execute format('revoke all on function private.%I(%s) from public,anon,authenticated',f.proname,signature);
  execute format('grant execute on function private.%I(%s) to service_role',f.proname,signature);
  body:=case when f.proretset then format('return query select * from private.%I(%s);',f.proname,coalesce(callargs,'')) when f.prorettype='void'::regtype then format('perform private.%I(%s); return;',f.proname,coalesce(callargs,'')) else format('return private.%I(%s);',f.proname,coalesce(callargs,'')) end;
  execute format('create function public.%I(%s) returns %s language plpgsql security definer set search_path=%L as %L',f.proname,args,result,'', 'begin '||guard||' '||body||' end;');
  execute format('revoke all on function public.%I(%s) from public,anon',f.proname,signature);
  execute format('grant execute on function public.%I(%s) to authenticated,service_role',f.proname,signature);
 end loop;
end $wrap$;
commit;
